\caption{LEO satellite grant-free access with multi-frame AFDM pilot
transmission. The insets show the frame structure of active device $k$
and the satellite UPA. Device activity is fixed over the $Q$ frames.
Satellite, footprint, and array artwork
is adapted from \cite[Fig.~1]{shen2025}.}
\label{fig:system-multiframe}
\end{figure}

The array response vector $\mathbf a_k$ at the satellite side can
be written as \cite{shen2025,li2023}
\begin{equation}
 [\mathbf a_k]_{n_z+M_zn_y}
 =e^{\mathrm j2\pi(d_yn_y\mu_{y,k}+d_zn_z\mu_{z,k})/\lambda},
 \label{eq:upa}
\end{equation}
where $n_z=0,\ldots,M_z-1$, $n_y=0,\ldots,M_y-1$,
$\lambda$ is the wavelength, and $d_v$ is the spacing between
adjacent antennas along the $v$-axis with $v\in\{y,z\}$.
Here $\mu_{z,k}$ and $\mu_{y,k}$ are the directional cosines along
the z-axis and y-axis, respectively.

The time-domain transmitted signal is generated through the inverse
discrete affine Fourier transform (IDAFT) applied to $\mathbf p_{qk}$,
mathematically formulated as \cite{ding2026}

\begin{equation}
 s_{qk}[t]=\frac{1}{\sqrt N}\sum_{n=0}^{N-1}
 P_{qkn}e^{\mathrm j2\pi(c_1t^2+c_2n^2+nt/N)},
 \label{eq:afdm-time-signal}
\end{equation}
where $t=0,\ldots,N-1$, and $c_1$ and $c_2$ are AFDM modulation
parameters.
The signal in \eqref{eq:afdm-time-signal} can be represented in matrix
form as \cite{ding2026}
\[
 \mathbf s_{qk}=\mathbf F_{\rm A}^{\mathsf H}\mathbf p_{qk},
\]
where
\begin{equation}
 \begin{gathered}
 \mathbf F_{\rm A}
 =\left[\frac{1}{\sqrt N}e^{-\mathrm j2\pi(c_2r^2+rt/N+c_1t^2)}
 \right]_{r,t=0}^{N-1}
 \end{gathered}
 \label{eq:daft}
\end{equation}
denotes the discrete affine Fourier transform (DAFT) matrix.
Here $T_s=1/(N\Delta f)$ gives the sampling interval, with
$\Delta f$ denoting the subcarrier spacing.

Assume that the chirp-periodic prefix (CPP) length is greater than
or equal to the maximum differential delay, i.e.,
$N_{\rm CPP}T_s\geq\max_{k,\ell}\tau_{k\ell}$.
The CPP is given by \cite{bemani2022}
\begin{equation}
 \begin{gathered}
 s_{qk}[t]=e^{\mathrm j2\pi c_1(t^2-\langle t\rangle_N^2)}
 s_{qk}[\langle t\rangle_N],\\
 -N_{\rm CPP}\leq t<0,
 \end{gathered}
 \label{eq:cpp}
\end{equation}
where $\langle x\rangle_N=x-N\lfloor x/N\rfloor$ and
$2Nc_1\in\mathbb N_+$.
Each AFDM frame spans a duration of $T_{\rm frame}=(N+N_{\rm CPP})T_s$.

To account for fractional delays, we define the transmit waveform
for the $n$th chirp subcarrier at time $\xi T_s$ as \cite{huang2026,bemani2023thesis}
\begin{equation}
 \varphi_n(\xi)=\frac{1}{\sqrt N}
 e^{\mathrm j2\pi[c_2n^2+c_1\xi^2+nw_\xi/N-\zeta_n(w_\xi)w_\xi]},
 \label{eq:continuous-waveform}
\end{equation}
where $w_\xi=\langle\xi\rangle_N$ and
$\zeta_n(w)=\lfloor2c_1w+n/N\rfloor$.
Note that $\varphi_n(t)=[\mathbf F_{\rm A}^{\mathsf H}]_{tn}$ for
$t=0,\ldots,N-1$, while $\varphi_n(\xi)$ satisfies
\eqref{eq:cpp} for $\xi<0$.

Denote by $H_k^{(q)}\in\mathbb C^{M\times N\times N}$ the effective
channel from the $k$th device to the satellite during the $q$th AFDM
frame, after removing the CPP and applying the DAFT.
For $q=0$, the effective channel $H_k=H_k^{(0)}$ can be expressed as
\begin{equation}
 H_{kmrn}
 =[\mathbf a_k]_m\sum_{\ell=1}^{L_k}g_{k\ell}
 [\mathbf G(\tau_{k\ell}/T_s,\nu_k;N_{\rm CPP})]_{rn},
 \label{eq:channel}
\end{equation}
where $n$ and $r$ correspond to the transmitted and received
symbols, respectively, and $m=0,\ldots,M-1$.
For a path with gain $1$, delay $dT_s$, and Doppler shift $\nu$,
the channel response can be expressed in a matrix form as

\begin{equation}
 \begin{gathered}
 \mathbf G(d,\nu;g)=\mathbf F_{\rm A}\mathbf D_{\nu,g}\mathbf B_d,\\
 \mathbf D_{\nu,g}=\diag\{e^{\mathrm j2\pi\nu T_s(g+t)}\}_{t=0}^{N-1},\\
 [\mathbf B_d]_{tn}=\varphi_n(t-d),
 \end{gathered}
 \label{eq:path-operator-system}
\end{equation}
where $t_{\rm c}=(g+t)T_s$ for $t=0,\ldots,N-1$ after removing
the CPP, and $g=N_{\rm CPP}$ for frame $0$. The operator
$\diag\{\cdot\}$ forms a diagonal matrix from its listed entries.
Appendix~\ref{app:afdm-model} gives the derivation and the expression for integer $d$.

Based on \eqref{eq:path-operator-system} with
$g=g_q=N_{\rm CPP}+q(N+N_{\rm CPP})$, we can derive the effective
channel in the $q$th AFDM frame as
\begin{equation}
 \begin{gathered}
 H_k^{(q)}=e^{\mathrm jq\beta_k}H_k,\\
 \beta_k=2\pi\!\left(\nu_kT_{\rm frame}
 -\left\lfloor\nu_kT_{\rm frame}+\frac12\right\rfloor\right),
 \end{gathered}
 \label{eq:twc-frame-channel}
\end{equation}
where $\beta_k\in[-\pi,\pi)$.
The phase rotation $e^{\mathrm jq\beta_k}$ accumulates across multiple frames,
while $H_k$ remains approximately constant over $Q$ consecutive frames.
The pilot symbols including this phase rotation are given by
\begin{equation}
 A_{qkn}=P_{qkn}e^{\mathrm jq\beta_k}.
 \label{eq:effective-pilot}
\end{equation}

After removing the CPP and applying the DAFT, the received signal
$\mathbf Y_q\in\mathbb C^{M\times N}$ during the $q$th AFDM
frame is given by \cite{cai2026}
\begin{equation}
 Y_{qmr}=[\mathbf Y_q]_{mr}
 =\sum_{k=1}^K\sum_{n=0}^{N-1}A_{qkn}X_{kmrn}+W_{qmr},
 \label{eq:observation-tensor}
\end{equation}
where $\mathbf W_q=[W_{qmr}]_{m,r}\in\mathbb C^{M\times N}$ is an
AWGN matrix with the elements i.i.d. drawn from $\CN(0,\sigma^2)$.

\begin{equation}
 \begin{aligned}
 &q(\mathbf X,\{H_k\}_{k=1}^{K},\{\alpha_k\}_{k=1}^{K}\mid\mathbf Y)\\
 &\quad\propto\prod_{j=1}^{MN}p(\mathbf y_j\mid\mathbf x_j)\\
 &\qquad\times\prod_{k=1}^{K}
 p(X_k\mid H_k,\alpha_k)q_{\rm tr}(H_k)p(\alpha_k),
 \end{aligned}
 \label{eq:working-posterior}
\end{equation}
where $\mathbf x_j\in\mathbb C^{KN}$ and $\mathbf y_j\in\mathbb C^Q$
denote the $j$th column of $\mathbf X$ and $\mathbf Y$, respectively.
Here
$p(\mathbf y_j\mid\mathbf x_j)=\CN(\mathbf y_j;
\widehat{\mathbf A}\mathbf x_j,\widehat\sigma^2\I_Q)$,
$p(X_k\mid H_k,\alpha_k)$ enforces $X_k=\alpha_kH_k$, and
$p(\alpha_k)=\rho^{\alpha_k}(1-\rho)^{1-\alpha_k}$.
The MMSE estimate of $X_k$ and the posterior probability of activity for the
$k$th device are given by

\begin{equation}
 \begin{aligned}
 X_k^{\rm MMSE}&=\E_q[X_k\mid\mathbf Y],\\
 p_k^{\rm Bayes}&=q(\alpha_k=1\mid\mathbf Y).
 \end{aligned}
 \label{eq:targets}
\end{equation}

