We incorporate the estimated channel mean and variance into message passing through
a site approximation to the channel prior \cite[Sec.~2.1]{vehtari2020},
of the form $\CN(\vect(H_k);\vect(E_k),c_k\I_D)$.
Dividing the Gaussian approximation with mean $F_k$ and variance
$\tau^{\rm post}$ by the input likelihood gives
\begin{equation}
 c_k=((\tau^{\rm post})^{-1}-v^{-1})^{-1},\qquad
 E_k=c_k\left(\frac{F_k}{\tau^{\rm post}}-\frac{R_k}{v}\right).
 \label{eq:site-update}
\end{equation}

Multiplying this site by the current Gaussian input likelihood gives the
conditional channel mean and variance
\begin{equation}
 t_k=\frac{c_kv}{c_k+v},\qquad
 \mu_k=\frac{c_kR_k+vE_k}{c_k+v}.
 \label{eq:conditional-moments}
\end{equation}

\begin{figure}[!t]
\centering
\begin{minipage}{0.96\linewidth}
\hrule\vspace{5pt}
\textbf{Algorithm 1: GP-MP-CCD for JADCE}\par
\textbf{Input:} received pilots, pilot symbols $\{P_{qkn}\}$, available phases,
activity prior $\rho$, and trained $f_\theta,z_\phi$.\par
\textbf{Output:} channel estimates, activity probabilities, and decisions.\par
\begin{enumerate}[leftmargin=1.8em,itemsep=2pt,topsep=4pt]
 \item Form $\widehat{\mathbf A}$ and $\widehat\sigma^2$; initialize as above
 and normalize as in Section~\ref{sec:frontend}. Compute the thin SVD and
 draw one random sign vector per device, reused across iterations.
 \item \textbf{for} $i=1,\ldots,I_{\max}$ \textbf{do}
 \item \textbf{MFLE:} Compute \eqref{eq:linear-mean}--\eqref{eq:linear-extrinsic}
 using \eqref{eq:linear-fraction}; apply \eqref{eq:input-damping}
 for $i\geq2$, and set
 $v^{(i)}=\kappa^{(i)}\bar v^{(i)}$.
 \item \textbf{GPJD:} If $v$ lies in the training interval,
 evaluate $F_k$, \eqref{eq:derivative-trace}, and
 \eqref{eq:activity-probability}. Apply \eqref{eq:pooled-variance}
 and update the sites by \eqref{eq:site-update} if $\tau^{\rm post}<v$;
 otherwise retain them.
 \item Otherwise, retain the sites and obtain $p_k$ from
 \eqref{eq:gaussian-evidence}.
 \item Compute $\mu_k,t_k$, $\widehat X_k$, and
 $\mathbf C_{X,k}$ by \eqref{eq:conditional-moments},
 \eqref{eq:mixture}, and \eqref{eq:joint-spatial-covariance}.
 \item Update $\kappa^{(i+1)}$ by \eqref{eq:query-variance-update}.
 Form \eqref{eq:nonlinear-extrinsic} using $v^{(i)}$, with clipping
 and output damping as in Section~\ref{sec:frontend}.
 \item Check the conditions in Section~\ref{sec:stopping-criteria}
 and update the stopping history; \textbf{break} if they hold.
 \item[]\textbf{end for}
 \item Return $s\widehat X_k$, $s\mu_k$, $p_k$, and
 $\widehat\alpha_k=\mathbf1\{p_k\geq1/2\}$.
\end{enumerate}
