\subsection{Parameter Estimation and Numerical Implementation}
\label{sec:frontend}
\label{sec:variance-update}
\label{sec:damping}

Minimizing the expected Gaussian negative log likelihood over the input
variance $v$, with the current approximate posterior \eqref{eq:mixture}
held fixed \cite[Sec.~III-A]{vila2013}, gives
\begin{equation}
 v_{\rm tar}=\frac{1}{KD}\sum_{k=1}^K
 \norm{R_k-\widehat X_k}_F^2+\overline t_X.
 \label{eq:query-variance-target}
\end{equation}

At iteration $i$, we use $v^{(i)}=\kappa^{(i)}\bar v^{(i)}$, where $\bar
v^{(i)}$ denotes the damped MFLE variance.
With damping factor $\eta\in(0,1]$, the next scale is
\begin{equation}
 \kappa^{(i+1)}=(1-\eta)\kappa^{(i)}
       +\eta\frac{v_{\rm tar}^{(i)}}{\bar v^{(i)}}.
 \label{eq:query-variance-update}
\end{equation}

For normalization, we divide $(H_k,X_k,\mathbf Y,\mathbf W)$ by the training-channel
root mean square $s$ and the noise variance by $s^2$, retaining their
symbols and leaving the pilot matrix unchanged.
For $i\geq2$, the MFLE output is damped as \cite[Sec.~V-B1]{cai2026}
\begin{equation}
 \begin{aligned}
 R_k^{(i)}&=(1-\eta)R_k^{(i-1)}+\eta R_{{\rm L},k}^{(i)},\\
 \bar v^{(i)}&=(1-\eta)\bar v^{(i-1)}+\eta v_{\rm L}^{(i)}.
 \end{aligned}
 \label{eq:input-damping}
\end{equation}

For numerical evaluation of \eqref{eq:nonlinear-extrinsic}, we replace
$b=\overline t_X/v$ by $b=\clip(\overline t_X/v,\varepsilon,1-\varepsilon)$,
where $0<\varepsilon<1/2$.
Here $\clip(x,a,b)=\min\{b,\max\{a,x\}\}$.
The feedback is then damped with the same weight:
\begin{equation}
 \begin{aligned}
 X_k^{{\rm pri},(i)}
 &=(1-\eta)X_k^{{\rm pri},(i-1)}+\eta X_{k,\rm out}^{(i)},\\
 \gamma^{(i)}
 &=(1-\eta)\gamma^{(i-1)}+\eta\gamma_{\rm out}^{(i)}.
 \end{aligned}
 \label{eq:output-damping}
\end{equation}

For fixed phases and $Q\leq KN$, the thin singular value decomposition
(SVD), $\widehat{\mathbf A}=\mathbf U\diag(s_1,\ldots,s_Q)\mathbf V^{\mathsf H}$,
is reused across iterations, where $s_a$ are the singular values.
The scalar updates in
\eqref{eq:linear-variance}--\eqref{eq:linear-extrinsic} can be written as
\begin{equation}
 f_{\rm L}=\frac{1}{KN}\sum_{a=1}^{Q}
 \frac{\gamma s_a^2}{\widehat\sigma^2+\gamma s_a^2},\qquad
 t_{\rm L}=\gamma(1-f_{\rm L}),\qquad
 v_{\rm L}=\frac{t_{\rm L}}{f_{\rm L}}.
 \label{eq:linear-fraction}
\end{equation}

For $Q\leq KN$, select distinct DFT rows
$r_q\in\{0,\ldots,KN-1\}$, a column permutation
$\{c_{kn}\}_{k,n}$ of the same set, and independent phases
$\phi_{kn}\sim\mathcal U[0,2\pi)$. The pilots are
\begin{equation}
 \begin{gathered}
 P_{qkn}=\sqrt{\frac{E_p}{N}}
 e^{-\mathrm j2\pi r_qc_{kn}/(KN)}e^{\mathrm j\phi_{kn}},\\
 \sum_{n=0}^{N-1}|P_{qkn}|^2=E_p.
 \end{gathered}
 \label{eq:pilot}
\end{equation}
The total pilot energy per device is $QE_p$.

Independent Bernoulli activities with nominal probability $p$ are
conditioned on at least one active device. The receiver prior uses the
resulting marginal $\rho=p/[1-(1-p)^K]$.
For the clean signal $\mathbf Y_0=\mathbf A\mathbf X$, set
\begin{equation}
 \sigma^2=\frac{\norm{\mathbf Y_0}_F^2}{QMN}
 10^{-\mathrm{SNR}_{\rm dB}/10}.
 \label{eq:snr}
\end{equation}

\subsubsection{Channel Samples and Training}
\label{sec:training-settings}
Training and validation use $50{,}000$ and $5{,}000$ clean
$16\times16\times16$ channels from disjoint scenes, four per scene before
activity masking.
The denoiser uses Adam for $200$ epochs with batch size $64$, initial
learning rate $10^{-4}$, and exponential moving average decay $0.999$;
validation loss under fixed noise realizations selects the model.
The white-noise reference uses the same clean channels and number of epochs.

\begin{equation}
 \mathbf R_{\rm corr}=(1-\xi_{\rm corr})\I_{16}
   +\xi_{\rm corr}\frac{16\mathbf Z_{\rm tr}\mathbf Z_{\rm tr}^{\mathsf H}}{\tr(\mathbf Z_{\rm tr}\mathbf Z_{\rm tr}^{\mathsf H})},
 \label{eq:simulation-colored-covariance}
\end{equation}
where $\mathbf Z_{\rm tr}\in\mathbb C^{16\times4}$ has independent $\CN(0,1)$
entries and $\xi_{\rm corr}$ is uniform on $[0,0.5]$.
We then freeze the denoiser and train the classifier from random
initialization by \eqref{eq:classifier-loss}, using batch size $32$,
initial learning rate $3\times10^{-4}$, and $100$ epochs, with validation
model selection. Classifier training and receiver evaluation use
$\mathbf C=v\I$.

Outside the training interval $[v_{\min},v_{\max}]=[10^{-3},10^2]$,
the retained sites give
\begin{equation}
 \begin{aligned}
 \ell_k^{\rm G}&=\frac{\norm{R_k}_F^2}{v}
 -\frac{\norm{R_k-E_k}_F^2}{c_k+v}
 -D\log\left(1+\frac{c_k}{v}\right),\\
 p_k&=\sigmoid(\logit\rho+\ell_k^{\rm G}).
 \end{aligned}
 \label{eq:gaussian-evidence}
\end{equation}

\subsubsection{Evaluation Metrics}
For scene indices $e\in\mathcal T$ at a given condition, the
normalized mean-squared error (NMSE) is
\begin{equation}
 \mathrm{NMSE}_{\rm dB}
 =10\log_{10}\frac{\sum_{e\in\mathcal T}\sum_{k=1}^{K}
 \norm{\widehat X_{ek}-X_{ek}}_F^2}
 {\sum_{e\in\mathcal T}\sum_{k=1}^{K}\norm{X_{ek}}_F^2},
 \label{eq:simulation-nmse}
\end{equation}
where $X_{ek}=\alpha_{ek}H_{ek}$. Errors on inactive devices are
included. For direct channel denoising, $X$ is replaced by $H$ and
the sums run over the individual channel samples. The activity error
rate (AER) is
\begin{equation}
 \mathrm{AER}=\frac{N_{\rm MD}+N_{\rm FA}}{K|\mathcal T|},
 \label{eq:simulation-aer}
\end{equation}
where $N_{\rm MD}$ and $N_{\rm FA}$ count missed detections and false
alarms, respectively.

