 \begin{aligned}
 \mathbf G_0(d,\nu)&=e^{-\mathrm j2\pi c_1d^2}\mathbf G(d,\nu;0),\\
 [\mathbf h_k^{\rm p}(d,\nu)]_{qN+r}
 &=e^{\mathrm j2\pi\nu qT_{\rm frame}}
 \sum_{n=0}^{N-1}[\mathbf G_0(d,\nu)]_{rn}P_{qkn}.
 \end{aligned}
 \label{frontend:eq:phase-atom}
\end{equation}
Here $\mathbf h_k^{\rm p}(d,\nu)\in\mathbb C^{QN}$. Search $d\in[0,N)$ and
$|\nu|\leq\nu_{\max}$, where $\nu_{\max}$ is the maximum absolute
Doppler shift in the channel model. Since
$2Nc_1\in\mathbb N_+$, shifts by integer multiples of $N$ change
the operator only by a scalar phase absorbed by the fitted gains.
With $\mathbf h_k^{\rm p}=\mathbf h_k^{\rm p}(d_k,\nu_k)$ and
$\mathbf b_k\in\mathbb C^M$, minimize

\begin{equation}
 \min_{\{d_k,\nu_k,\mathbf b_k\}}
 \left\|\mathbf Y_{\rm s}-\sum_{k=1}^K
 \mathbf h_k^{\rm p}\mathbf b_k^{\mathsf T}\right\|_F^2.
 \label{frontend:eq:phase-fit}
\end{equation}
When updating device $k$, we fix the other contributions and define
$\mathbf Z_k=\mathbf Y_{\rm s}-\sum_{j\ne k}
\mathbf h_j^{\rm p}\mathbf b_j^{\mathsf T}$. For a given $(d,\nu)$, the
least-squares gain and the resulting objective are given by
\begin{equation}
 \begin{aligned}
 \mathbf b_k^{\mathsf T}(d,\nu)
 &=\frac{\mathbf h_k^{\rm p}(d,\nu)^{\mathsf H}\mathbf Z_k}
 {\|\mathbf h_k^{\rm p}(d,\nu)\|^2},\\
 J_k(d,\nu)&=\|\mathbf Z_k\|_F^2-
 \frac{\|\mathbf h_k^{\rm p}(d,\nu)^{\mathsf H}\mathbf Z_k\|^2}
 {\|\mathbf h_k^{\rm p}(d,\nu)\|^2}.
 \end{aligned}
 \label{frontend:eq:phase-variable-projection}
\end{equation}
Variable projection eliminates the gains \cite{oleary2013}.
Coarse correlations initialize candidates. Doppler shifts yielding the same frame phase $\beta$ are
$\nu_j=(\beta+2\pi j)/(2\pi T_{\rm frame})$, $j\in\mathbb Z$,
within the search range. Rank them using \eqref{frontend:eq:phase-atom}
and refine by L-BFGS-B \cite{zhu1997}, accepting updates that do not
increase the residual beyond numerical tolerance within an interval where the waveform is differentiable. After each sweep,
jointly re-estimate the gains and retain the previous position as a candidate.
The estimated Doppler gives $\widehat\beta_k$ and $\widehat{\mathbf A}$
through \eqref{eq:twc-frame-channel}--\eqref{eq:effective-pilot}.

Substituting the basis waveform in \eqref{eq:continuous-waveform}
into \eqref{eq:path-operator-system} gives
\begin{equation}
 \begin{split}
 G_{rn}
 &=\frac{e^{\mathrm j2\pi[c_1d^2+c_2(n^2-r^2)-nd/N+\nu T_sg]}}{N}\\
 &\quad\times\sum_{t=0}^{N-1}
 e^{\mathrm j2\pi[(n-r)/N-2c_1d+\nu T_s]t}
 e^{\mathrm j2\pi\zeta_{tn}d}.
 \end{split}
 \label{eq:path-entry-expansion}
\end{equation}
where $\zeta_{tn}=\zeta_n(\langle t-d\rangle_N)$.
Integer phase factors cancel because $t,\zeta_{tn}$ are integers
and $w_{t-d}-(t-d)$ is an integer multiple of $N$.
For integer $d$, the final factor is one, giving

\begin{align}
 \mathbf G(d,\nu;g)
 &=\mathbf F_{\rm A}\mathbf D_{\nu,g}\bm\Omega_d
   \bm\Pi_{d\bmod N}\mathbf F_{\rm A}^{\mathsf H},
 \label{eq:integer-operator}\\
 [\bm\Omega_d]_{tt}
 &=e^{\mathrm j2\pi c_1[(t-d)^2-\langle t-d\rangle_N^2]},
 \label{eq:integer-prefix-phase}
\end{align}
where $[\bm\Pi_l\mathbf s]_t=s[\langle t-l\rangle_N]$.
The remainder of $d$ determines the cyclic shift, whereas the
full delay determines the CPP phase. The same expression therefore
covers delays extending over multiple useful-symbol periods.
